TenantAppManagement = {
    init: async function(app, container, tenant) {
        container = container || $(".component[name=TenantAppManagement]");
        api.addToMetaCache([{ Name: "ContentManagement", Types: [[meta[ContentManagement/App]]] }]);
        var tenantId = tenant.Id.replaceAll("'", "''");
        var ds = await model.getDatasource({ endpoint: "ContentManagement/App", odataAppend: "?$filter=TenantId eq '" + tenantId + "'&$expand=Cultures" });
        var grid = new GridWidget(container, ds);
        grid.groupable = false;
        grid.filterable = true;
        grid.columns = [
            { field: "Name", title: "[resource_shortdisplayname[name]]" },
            { field: "Domain", title: "[resource_shortdisplayname[domain]]" },
            { title: "[resource_displayname[visit]]", width: 96, editable: false, template: "<a class='btn btn-sm btn-outline-primary' href='https://#=Domain#/' target='_blank' rel='noopener'><span class='k-icon k-i-share'></span>[resource_displayname[visit]]</a>" }
        ];
        grid.detailTemplate = "<div name='tenantAppDetails'></div>";
        grid.detailExpand = function(e) {
            var selectedApp = grid.dataItem(e.masterRow);
            var host = $("[name=tenantAppDetails]", e.detailRow);
            if (host.data("app-initialised")) return;
            host.data("app-initialised", true);
            loadComponent(host, "AppManagement", async function() {
                var component = $(".component[name=AppManagement]", host);
                await AppManagement.init(selectedApp, component);
            });
        };
        await grid.init();
    }
};
